import { useState } from "react";
import { StreamingResponse, useTextStream } from "@/registry/erbium/blocks/streaming-response";
import { Bubble, BubbleContent } from "@/registry/erbium/ui/bubble";
import { Button } from "@/registry/erbium/ui/button";
import { Message, MessageContent } from "@/registry/erbium/ui/message";
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/registry/erbium/ui/message-scroller";
import { simulateStream } from "../../streaming";

const question = "How should I name the new endpoints?";

const reply = `Name them after the **resource**, and let the method say what happens:

| Method | Path | Does |
| :----- | :--- | :--- |
| GET | \`/projects\` | Lists projects |
| POST | \`/projects\` | Creates one |
| DELETE | \`/projects/:id\` | Removes one |

A handler then reads like the route it serves:

\`\`\`ts
router.get("/projects", async (request) => {
  const projects = await listProjects(request.query);

  return Response.json({ projects });
});
\`\`\`

Keep verbs out of paths. If an action fits no method, give it a noun of its own, such as
\`/projects/:id/exports\`.
`;

const UserMessage = ({ id, children }: { id: string; children: string }) => (
  <MessageScrollerItem messageId={id} scrollAnchor>
    <Message align="end">
      <MessageContent>
        <Bubble>
          <BubbleContent>{children}</BubbleContent>
        </Bubble>
      </MessageContent>
    </Message>
  </MessageScrollerItem>
);

export default function MessageScrollerStreamingReplyExample() {
  const { error, start, status, stop, text } = useTextStream();
  const [turn, setTurn] = useState(0);
  const busy = status === "pending" || status === "streaming";

  const ask = () => {
    setTurn((current) => current + 1);
    void start((signal) => simulateStream(reply, { signal }));
  };

  return (
    <MessageScrollerProvider autoScroll>
      <div className="grid w-full max-w-md gap-related">
        <Button className="justify-self-start" size="sm" onClick={busy ? stop : ask}>
          {busy ? "Stop" : "Ask"}
        </Button>
        <MessageScroller className="h-96 rounded-lg border">
          <MessageScrollerViewport>
            <MessageScrollerContent aria-busy={busy} className="gap-4 p-4">
              <UserMessage id="greeting">Can you help me design an API?</UserMessage>
              <MessageScrollerItem messageId="offer">
                <StreamingResponse text="Of course. What would you like to decide first?" />
              </MessageScrollerItem>
              {turn === 0 ? null : (
                <>
                  <UserMessage key={`question-${turn}`} id={`question-${turn}`}>
                    {question}
                  </UserMessage>
                  <MessageScrollerItem key={`reply-${turn}`} messageId={`reply-${turn}`}>
                    <StreamingResponse text={text} status={status} error={error?.message} />
                  </MessageScrollerItem>
                </>
              )}
            </MessageScrollerContent>
          </MessageScrollerViewport>
          <MessageScrollerButton />
        </MessageScroller>
      </div>
    </MessageScrollerProvider>
  );
}

/*
 * A stand-in for a model's reply, so streaming examples run without a server. In an app, pass
 * `useTextStream` the response body or the text stream of your model SDK.
 */

interface SimulatedStreamOptions {
  signal?: AbortSignal;
  /** Characters per chunk. */
  chunkSize?: number;
  /** Milliseconds between chunks. */
  interval?: number;
  /** How long the "model" thinks before the first chunk. */
  delay?: number;
}

const wait = async (milliseconds: number) => {
  // oxlint-disable-next-line promise/avoid-new -- a timer has no promise form in browsers.
  await new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
};

/**
 * Streams `text` a few characters at a time until it ends or `signal` aborts.
 *
 * @yields {string} The next chunk of `text`.
 */
const simulateStream = async function* simulateStream(
  text: string,
  { signal, chunkSize = 6, interval = 24, delay = 600 }: SimulatedStreamOptions = {},
) {
  await wait(delay);

  for (let start = 0; start < text.length; start += chunkSize) {
    if (signal?.aborted === true) {
      return;
    }

    yield text.slice(start, start + chunkSize);
    // Chunks arrive in order, one after another.
    // oxlint-disable-next-line no-await-in-loop
    await wait(interval);
  }
};

export { simulateStream };
